def apply_checks(apps):
 for a in apps:
  if a['id'] not in UPDATES: continue
  update=dict(UPDATES[a['id']])
  review=update.pop('fresh_check')
  a.update(update)
  a['fresh_source_check']={'date':'2026-11-05','reviewer':'root assistant; not an independent referee','scope':'Source interface and explicitly listed translations only; not the entire application or its internal premises.','result':review}
